export interface ItineraryDay {
    day: string;
    title: string;
    description: string;
}

// One real product sold from several cities. The same route differs only by the
// flight legs, so each departure carries its own itinerary/price/dates; everything
// it omits falls back to the parent tour. Lets us collapse "...вылет из X" duplicates
// into a single card + an in-page switcher, instead of a separate card per city.
export interface TourDeparture {
    city: string;
    price?: string;
    dates?: string;
    itinerary?: ItineraryDay[];
    included?: string[];
    notIncluded?: string[];
}

export interface Tour {
    id: string;
    category: 'china' | 'russia' | 'hot-deals' | 'japan';
    title: string;
    subtitle: string;
    duration: string;
    route: string;
    dates: string;
    price: string;
    image: string;        // day cover (also the fallback when no night variant)
    imageNight?: string;  // optional night cover — crossfades with the theme toggle
    itinerary: ItineraryDay[];
    included: string[];
    notIncluded: string[];
    departures?: TourDeparture[];  // when present (≥2), the city of departure is a switcher
}

